#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>

int main() {
    // Try to find and click the Open button using accessibility API
    AXUIElementRef systemWideElement = AXUIElementCreateSystemWide();

    // Get focused application
    AXUIElementRef focusedApp;
    AXUIElementCopyAttributeValue(systemWideElement, kAXFocusedApplicationAttribute, (CFTypeRef*)&focusedApp);

    // Get main window
    CFArrayRef windows;
    AXUIElementCopyAttributeValue(focusedApp, kAXWindowsAttribute, (CFTypeRef*)&windows);

    if (windows) {
        AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windows, 0);

        // Try to find Open button
        CFArrayRef buttons;
        AXUIElementCopyAttributeValue(window, kAXChildrenAttribute, (CFTypeRef*)&buttons);

        if (buttons) {
            CFIndex count = CFArrayGetCount(buttons);
            for (CFIndex i = 0; i < count; i++) {
                AXUIElementRef button = (AXUIElementRef)CFArrayGetValueAtIndex(buttons, i);
                CFStringRef role;
                AXUIElementCopyAttributeValue(button, kAXRoleAttribute, (CFTypeRef*)&role);

                if (CFEqual(role, kAXButtonRole)) {
                    CFStringRef title;
                    AXUIElementCopyAttributeValue(button, kAXTitleAttribute, (CFTypeRef*)&title);
                    if (CFStringFind(title, CFSTR("Open"), 0).location != kCFNotFound) {
                        AXUIElementPerformAction(button, kAXPressAction);
                        printf("Clicked Open button\n");
                        return 0;
                    }
                    CFRelease(title);
                }
                CFRelease(role);
            }
            CFRelease(buttons);
        }
        CFRelease(window);
    }

    printf("Open button not found\n");
    return 1;
}
EOF

